"use strict";const dropdowns=document.querySelectorAll("[data-dropdown]");for(const o of dropdowns)o.addEventListener("toggle",()=>{if(o.open)for(const e of dropdowns)e!==o&&(e.open=!1)});function closeOutsideDropdown(o){for(const e of dropdowns)e.open&&!e.contains(o)&&(e.open=!1)}document.addEventListener("click",o=>closeOutsideDropdown(o.target)),document.addEventListener("focusin",o=>closeOutsideDropdown(o.target)),document.addEventListener("keydown",o=>{if("Escape"===o.key)for(const e of dropdowns)if(e.open&&e.contains(o.target)){o.preventDefault(),e.open=!1,e.querySelector("summary").focus();break}});